1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
25	
26	const applyFirstInsuranceSurcharge = (amount: number): number =>
27	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
28	
29	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
30	
31	export const quote = (
32	  customer: Customer,
33	  items: Item[],
34	  contractIndex: number,
35	): number => {
36	  const base = items.reduce((sum, item) => sum + basePremium(item), 0);
37	  return roundInMhpcoFavor(applyFirstInsuranceSurcharge(base) + PROCESSING_FEE);
38	};
39	
40	export const claim = (): number => {
41	  return undefined as unknown as number;
42	};
