1	import { describe, it, expect } from "vitest";
2	import { quote, claim } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Edge case: empty list
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [], 0)).toBe(5);
8	  });
9	
10	  // Base premiums for single main items (base + 10% first insurance + 5 fee)
11	  it("single sword → base premium 100 G (total 100 + 10 first + 5 fee = 115)", () => {
12	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }], 0)).toBe(115);
13	  });
14	  it("single amulet → base premium 60 G (total 60 + 6 first + 5 fee = 71)", () => {
15	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }], 0)).toBe(71);
16	  });
17	  it("single staff → base premium 80 G (total 80 + 8 first + 5 fee = 93)", () => {
18	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }], 0)).toBe(93);
19	  });
20	  it("single potion → base premium 40 G (total 40 + 4 first + 5 fee = 49)", () => {
21	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }], 0)).toBe(49);
22	  });
23	
24	  // Components
25	  it("single rune → base premium 25 G (total 25 + 2.5 first + 5 fee = 32.5 → 33 rounded up)", () => {
26	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }], 0)).toBe(33);
27	  });
28	  it("single moonstone → base premium 25 G (total 32.5 → 33 rounded up)", () => {
29	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }], 0)).toBe(33);
30	  });
31	
32	  // Building block of 3 alike components
33	  it.todo("2 runes → 50 G base premium (no block)");
34	  it.todo("3 runes → 60 G base premium (block applies)");
35	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
36	  it.todo("7 runes → 175 G base premium");
37	
38	  // "Alike" components — same type only
39	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
40	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
41	
42	  // Premium modifiers — item-specific
43	  it.todo("cursed sword adds 50% risk surcharge (50 G on base 100 G)");
44	  it.todo("highly enchanted sword (enchantment ≥ 5) adds 30% surcharge");
45	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
46	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
47	  it.todo("sword with enchantment 5 and cursed → both surcharges apply");
48	
49	  // Policy-wide modifiers
50	  it.todo("long-standing customer (≥ 2 years) receives 20% loyalty discount");
51	  it.todo("customer with exactly 2 years → loyalty discount applies");
52	  it.todo("first insurance carries 10% initial assessment surcharge");
53	  it.todo("15% discount on each contract after the first");
54	
55	  // Processing fee
56	  it.todo("a 5 G processing fee is added to every premium");
57	
58	  // Modifier scope on multi-item policies
59	  it.todo(
60	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of cursed item base) → 210 G before further modifiers and fee",
61	  );
62	
63	  // Rounding in MHPCO's favor
64	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
65	
66	  // Integration examples
67	  it.todo(
68	    "newcomer with cursed sword (steel, ench 3), 0 years → premium 165 G",
69	  );
70	  it.todo(
71	    "long-standing customer 2nd contract: cursed sword (steel, ench 7), 3 years → premium 160 G",
72	  );
73	  it.todo(
74	    "first insurance surcharge applies per item regardless of customer history",
